INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass MAC-Adressen immer vom Nutzer geändert werden können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hardwareseitig festgelegt"}, {"text": "Ja", "correct": false, "because": "Nur durch Spoofing änderbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich MAC-Adressen in einem IT-Netzwerk verwalte?', 3, '[{"text": "Eindeutigkeit", "correct": true, "because": "Sichert Identifikation"}, {"text": "Schnelle Änderung", "correct": false, "because": "Selten nötig"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen MAC-Adressen in der IT nützlich?', 5, '[{"text": "Eindeutige Zuordnung", "correct": true, "because": "Identifiziert Geräte"}, {"text": "Schicht-2-Nutzung", "correct": true, "because": "Für Datenlink-Schicht"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Merkmal"}, {"text": "Bunte Darstellung", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MAC-Adressen sind 48 Bit lang. b) Sie ändern sich bei jedem Neustart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Permanent zugeteilt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich MAC-Adressen in einem Netzwerk analysiere?', 4, '[{"text": "Geräteidentifikation", "correct": false, "because": "Kernfunktion"}, {"text": "Herstellercode", "correct": false, "because": "Teil der Adresse"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MAC-Adressen auf Schicht 3 arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 2 (Datenlink)"}, {"text": "Ja", "correct": false, "because": "Falsche Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich MAC-Adressen in einem Netzwerk nutze?', 3, '[{"text": "Geräteidentifikation", "correct": true, "because": "Sichert Zuordnung"}, {"text": "Schnellste Verbindung", "correct": false, "because": "Sekundär"}, {"text": "Weniger Adressen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei MAC-Adressen entscheidend?', 5, '[{"text": "Eindeutigkeit", "correct": true, "because": "Verhindert Konflikte"}, {"text": "Hexadezimalformat", "correct": true, "because": "Standarddarstellung"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Farbliche Markierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) MAC-Adressen sind weltweit eindeutig. b) Sie werden vom Nutzer vergeben. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hersteller vergeben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich MAC-Adressen in einem Netzwerk verwalte?', 4, '[{"text": "Netzwerkscanner", "correct": false, "because": "Erkennt Adressen"}, {"text": "MAC-Tabelle", "correct": false, "because": "Speichert Zuordnungen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind MAC-Adressen dasselbe wie IP-Adressen?', 2, '[{"text": "Nein", "correct": true, "because": "Verschiedene Schichten"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten MAC-Adressen in einem Netzwerk?', 4, '[{"text": "Eindeutige Identifikation", "correct": true, "because": "Sichert Gerätezuordnung"}, {"text": "Netzwerksicherheit", "correct": true, "because": "Ermöglicht Filterung"}, {"text": "Schnellere Server", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass MAC-Adressen nur für WLAN genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für LAN"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um MAC-Adressen in einem Netzwerk zu überprüfen?', 3, '[{"text": "ARP-Tabelle", "correct": true, "because": "Zeigt Zuordnungen"}, {"text": "Schnelle Software", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MAC-Adressen sind hardwaregebunden. b) Sie ändern sich bei Netzwerkwechsel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Permanent"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei MAC-Adressen?', 5, '[{"text": "Hersteller-ID", "correct": true, "because": "Teil der Adresse"}, {"text": "Geräte-ID", "correct": true, "because": "Macht eindeutig"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Bürogröße", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich MAC-Adressen in einem Netzwerk analysiere?', 3, '[{"text": "Netzwerkprotokolle", "correct": false, "because": "Beeinflussen Nutzung"}, {"text": "Gerätezuordnung", "correct": false, "because": "Kernfunktion"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Werden MAC-Adressen auf Schicht 3 genutzt?', 3, '[{"text": "Nein", "correct": true, "because": "Schicht 2 (Datenlink)"}, {"text": "Ja", "correct": false, "because": "Falsche Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MAC-Adressen für Sicherheitsfilter genutzt werden können?', 2, '[{"text": "Ja", "correct": true, "because": "MAC-Filter möglich"}, {"text": "Nein", "correct": false, "because": "Häufig verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für MAC-Adressen?', 4, '[{"text": "Eindeutigkeit", "correct": true, "because": "Sichert Identifikation"}, {"text": "Schnelle Änderung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]');
